INSERT INTO "announcement_templates" (name, title, title_bn, message, message_bn, priority, audience_type) VALUES
('Scheduled Maintenance', 'Scheduled Maintenance', 'নির্ধারিত রক্ষণাবেক্ষণ', 'The Gramer Bazar service will be temporarily unavailable from {{startTime}} to {{endTime}}.', 'গ্রামের বাজার সার্ভিসটি {{startTime}} থেকে {{endTime}} পর্যন্ত সাময়িকভাবে বন্ধ থাকবে।', 'IMPORTANT', 'EVERYONE'),
('Flash Sale', 'Flash Sale Started!', 'ফ্ল্যাশ সেল শুরু হয়েছে!', 'Special offers are now available. Shop now and save {{discount}}% on your orders today!', 'বিশেষ অফার এখন উপলব্ধ। আজই কেনাকাটা করুন এবং আপনার অর্ডারে {{discount}}% সাশ্রয় করুন!', 'NORMAL', 'EVERYONE'),
('Seller Update', 'Important Seller Update', 'গুরুত্বপূর্ণ সেলার আপডেট', 'We have updated our seller policy. Please review the latest information in your dashboard.', 'আমরা আমাদের সেলার নীতি আপডেট করেছি। অনুগ্রহ করে আপনার ড্যাশবোর্ডে সর্বশেষ তথ্য পর্যালোচনা করুন।', 'IMPORTANT', 'ROLE'),
('Rider Notice', 'Rider Notice: {{date}}', 'রাইডার বিজ্ঞপ্তি: {{date}}', 'Please check your latest delivery instructions and safety guidelines for today.', 'অনুগ্রহ করে আজকের জন্য আপনার সর্বশেষ ডেলিভারি নির্দেশাবলী এবং নিরাপত্তা নির্দেশিকা চেক করুন।', 'NORMAL', 'ROLE'),
('Customer Offer', 'Special Offer for {{userName}}!', '{{userName}} এর জন্য বিশেষ অফার!', 'Hello {{userName}}, you have a new exclusive offer waiting for you. Use code {{discountCode}} at checkout.', 'হ্যালো {{userName}}, আপনার জন্য একটি নতুন এক্সক্লুসিভ অফার অপেক্ষা করছে। চেকআউটে {{discountCode}} কোড ব্যবহার করুন।', 'NORMAL', 'EVERYONE')
